<?php
require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/cash.php';require_once __DIR__.'/../includes/cash_layout.php';require_once __DIR__.'/../includes/referrals.php';$user=require_role(ROLE_TRADER);$uid=(int)$user['id'];cash_header($user,'Referral Network');
try{$referralCode=referral_code($uid);$link=rtrim(APP_URL,'/').'/auth/register.php?ref='.$referralCode;$direct=cash_query('SELECT u.id,u.full_name,u.email,u.created_at FROM referral_members r JOIN users u ON u.id=r.user_id WHERE r.referrer_id=? ORDER BY u.created_at DESC',[$uid])->fetchAll();$all=cash_query('SELECT user_id,referrer_id FROM referral_members')->fetchAll();$users=cash_query("SELECT id,full_name,email FROM users WHERE role='trader'")->fetchAll();$um=[];foreach($users as $u)$um[(int)$u['id']]=$u;$children=[];foreach($all as $r)$children[(int)$r['referrer_id']][]=(int)$r['user_id'];$bonusSettings=cash_query('SELECT * FROM referral_settings WHERE id=1')->fetch();$bonusPlans=$bonusSettings&&(int)$bonusSettings['enabled']&&referral_lot_ensure_schema()?cash_query('SELECT name,price_minor,referral_bps FROM cash_lot_plans WHERE enabled=1 ORDER BY price_minor,id')->fetchAll():[];}catch(Throwable $e){$direct=[];$children=[];$um=[];$bonusPlans=[];echo '<div class="notice">Referral network is temporarily unavailable.</div>';}
function nx_ref_tree(int $id,array $children,array $um,int $depth=0):void{if($depth>=5||empty($children[$id]))return;echo '<ul class="ref-tree">';foreach($children[$id] as $cid){$u=$um[$cid]??null;if(!$u)continue;echo '<li><div class="ref-node"><span class="avatar">'.e(mb_substr($u['full_name'],0,1)).'</span><div><strong>'.e($u['full_name']).'</strong><small>'.e($u['email']).'</small></div></div>';nx_ref_tree($cid,$children,$um,$depth+1);echo '</li>';}echo '</ul>';}
?>
<section class="panel cash-body referral-share-panel"><div class="referral-section-head"><h3>Your Referral Code</h3><p class="referral-help">Share your code or invitation link with people you invite to NEXMERCE.</p></div><div class="referral-code-card"><div class="referral-code-value"><small>MY REFERRAL CODE</small><strong id="referral-code"><?= e($referralCode??'') ?></strong></div><button class="button secondary referral-copy-button" type="button" id="referral-code-copy">Copy code</button></div><div class="referral-link-block"><h4>Your Referral Link</h4><div class="referral-link-row"><input id="referral-link" readonly value="<?= e($link??'') ?>"><button class="button referral-copy-button" type="button" id="referral-copy">Copy link</button></div><p id="referral-copy-status" class="fine-print referral-copy-status" aria-live="polite"></p></div><div class="referral-count"><strong><?= count($direct) ?></strong><span>direct referrals</span></div><?php if($bonusPlans): ?><div class="bonus-grid"><?php foreach($bonusPlans as $bp): ?><span><?= e($bp['name']) ?> · <?= e(referral_lot_label($bp,$bonusSettings)) ?></span><?php endforeach ?></div><?php endif ?><p class="fine-print">Additional package bonus targets: $60 for 60 days after 3 invites; $200 for 75 days after 8 invites; $480 for 90 days. Qualification is shown for reference and can be reviewed by administration.</p></section>
<section class="panel cash-body referral-list-panel"><div class="panel-head"><div><h3>Referral List</h3><p>Members who registered directly using your referral code or referral link.</p></div><span class="chip"><?= count($direct) ?> Direct</span></div><div class="table-scroll"><table><thead><tr><th>#</th><th>Member</th><th>Email</th><th>Date Joined</th><th>Status</th></tr></thead><tbody><?php if(!$direct): ?><tr><td colspan="5">No direct referrals yet. Share your referral code or referral link to invite members.</td></tr><?php else: foreach($direct as $i=>$member): ?><tr><td><?= $i+1 ?></td><td><strong><?= e($member['full_name']) ?></strong></td><td><?= e($member['email']) ?></td><td><?= e(date('M d, Y',strtotime((string)$member['created_at']))) ?><small><?= e(date('h:i A',strtotime((string)$member['created_at']))) ?></small></td><td><span class="chip">Registered</span></td></tr><?php endforeach; endif ?></tbody></table></div></section>
<section class="panel cash-body"><h3>Referral Genealogy</h3><p>View members registered under your referral network.</p><div class="ref-root"><div class="ref-node root"><span class="avatar"><?= e(mb_substr($user['full_name'],0,1)) ?></span><div><strong><?= e($user['full_name']) ?></strong><small>You</small></div></div><?php nx_ref_tree($uid,$children,$um); ?></div></section><script src="/assets/js/referrals.js?v=1" defer></script><?php cash_footer(); ?>
